async def validate_promo_code(session: AsyncSession, code: str) -> PromoCode | None:
    from sqlalchemy import select, func
    result = await session.execute(
        select(PromoCode).where(func.lower(PromoCode.code) == func.lower(code))
    )
    promo = result.scalar_one_or_none()
    if not promo:
        return None
    if _is_promo_expired(promo):
        return None
    if _is_promo_maxed_out(promo):
        return None
    return promo"}

